// Outline JSON parsen und Sektionen als einzelne Items aufbereiten
const input = $input.all()[0].json;
let outline;
try {
  outline = typeof input.outline_json === 'string' ? JSON.parse(input.outline_json) : input.outline_json;
} catch(e) {
  // Fallback: versuche aus Markdown-Block zu parsen
  const match = (input.outline_json || '').match(/```(?:json)?\s*([\s\S]*?)```/);
  outline = match ? JSON.parse(match[1].trim()) : { sections: [], title_suggestion: input.keyword };
}

const sections = outline.sections || [];
const totalSections = sections.length;

// Jede Sektion als separates Item für den Loop
return sections.map((section, index) => ({
  json: {
    section_index: index,
    total_sections: totalSections,
    h2: section.h2 || '',
    h3_subsections: JSON.stringify(section.h3_subsections || []),
    infographic: JSON.stringify(section.infographic || null),
    key_points: JSON.stringify((section.h3_subsections || []).flatMap(s => s.key_points || [])),
    wdf_idf_terms_section: JSON.stringify((section.h3_subsections || []).flatMap(s => s.wdf_idf_terms || [])),
    internal_link: JSON.stringify((section.h3_subsections || []).map(s => s.internal_link).filter(Boolean)),
    title_suggestion: outline.title_suggestion || '',
    faq_section: JSON.stringify(outline.faq_section || []),
    all_internal_links: JSON.stringify(outline.internal_links || [])
  }
}));

// Claude-Antwort extrahieren
const items = $input.all();
return items.map((item, index) => {
  const content = item.json.content?.[0]?.text || item.json.choices?.[0]?.message?.content || '';
  return {
    json: {
      section_index: index,
      section_content: content
    }
  };
});

// Alle Sektionen zu einem Gesamtartikel zusammenfügen
const sections = $input.all()
  .sort((a, b) => a.json.section_index - b.json.section_index)
  .map(item => item.json.section_content);

const fullDraft = sections.join('\n\n---\n\n');

return [{ json: { full_draft: fullDraft, section_count: sections.length } }];

// Finalen Artikel extrahieren
const response = $input.all()[0].json;
const finalArticle = response.content?.[0]?.text || '';

return [{ json: { final_article: finalArticle } }];

// FAQ wird bereits im Artikel durch den Copywriter geschrieben
// Kein separates FAQ-Anhängen nötig
return [{ json: { faq_markdown: '', has_faq: false } }];

// BULLETPROOF Meta Parser - finds meta_title regardless of JSON structure
const response = $input.all()[0].json;
const content = response.content?.[0]?.text || '';

// Extract JSON
let rawMeta = null;
try {
  rawMeta = JSON.parse(content);
} catch(e) {
  const m = content.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (m) try { rawMeta = JSON.parse(m[1].trim()); } catch(e2) {}
  if (!rawMeta) {
    const b = content.match(/\{[\s\S]*\}/);
    if (b) try { rawMeta = JSON.parse(b[0]); } catch(e3) {}
  }
}

// Recursive search for meta_title in ANY structure
function findMeta(obj) {
  if (!obj || typeof obj !== 'object') return null;
  // Direct hit
  if (obj.meta_title) return obj;
  // Search in arrays
  if (Array.isArray(obj)) {
    for (const item of obj) {
      const found = findMeta(item);
      if (found) return found;
    }
  }
  // Search in object values
  for (const val of Object.values(obj)) {
    const found = findMeta(val);
    if (found) return found;
  }
  return null;
}

let meta = rawMeta ? findMeta(rawMeta) : null;

if (!meta) {
  const keyword = $('Extract Input Data').item.json.keyword || '';
  meta = {
    meta_title: keyword,
    meta_description: '',
    url_slug: keyword.toLowerCase().replace(/[^a-z0-9]+/g, '-'),
    focus_keyword: keyword
  };
}

meta.meta_title = meta.meta_title || '';
meta.meta_description = meta.meta_description || '';
meta.url_slug = meta.url_slug || '';
meta.focus_keyword = meta.focus_keyword || $('Extract Input Data').item.json.keyword || '';

// FAQ
let faqData = { has_faq: false, faq_markdown: '' };
try { faqData = $('Build FAQ Section').item.json; } catch(e) {}

const finalArticle = $('Extract Final Article').item.json.final_article || '';
const fullContent = faqData.has_faq ? finalArticle + faqData.faq_markdown : finalArticle;

return [{
  json: {
    meta: meta,
    full_content: fullContent,
    word_count: fullContent.split(/\s+/).length
  }
}];

// Prüfe ob ein bestehendes Google Doc übergeben wurde (von 01a/ClickUp)
const existingDocId = $('Extract Input Data').item.json.doc_id;
const existingDocUrl = $('Extract Input Data').item.json.doc_url;

if (existingDocId) {
  // Bestehendes Doc nutzen — kein neues erstellen
  return [{ json: { id: existingDocId, doc_url: existingDocUrl, used_existing: true } }];
} else {
  // Kein Doc vorhanden — Flag setzen, dass neues erstellt werden muss
  return [{ json: { id: '', doc_url: '', needs_creation: true } }];
}

// Markdown to Google Docs with tables as formatted text
const items = $input.all();
const item = items[items.length - 1].json;
const docId = item.id;
const docUrl = item.doc_url || `https://docs.google.com/document/d/${docId}/edit`;

const content = $('Parse Meta & Assemble Final').item.json.full_content || '';
const meta = $('Parse Meta & Assemble Final').item.json.meta || {};

const metaBlock = `META TITLE: ${meta.meta_title || ''}\nMETA DESCRIPTION: ${meta.meta_description || ''}\nURL SLUG: ${meta.url_slug || ''}\nFOCUS KEYWORD: ${meta.focus_keyword || ''}\n\n`;
const fullMarkdown = metaBlock + content;

const lines = fullMarkdown.split('\n');
const requests = [];
let plainText = '';
const formatOps = [];

let currentIdx = 1;

for (let lineNum = 0; lineNum < lines.length; lineNum++) {
  const line = lines[lineNum];

  // Skip table separator lines
  if (line.match(/^\|[\s\-:|]+\|$/)) continue;

  // Table rows - format as tab-separated text with bold header
  if (line.trim().startsWith('|') && line.trim().endsWith('|')) {
    const cells = line.split('|').filter(c => c.trim()).map(c => c.trim());
    const rowText = '| ' + cells.join(' | ') + ' |\n';
    const rowStart = currentIdx;
    plainText += rowText;

    // Check if this is the header row (first table row)
    const prevLine = lineNum > 0 ? lines[lineNum - 1] : '';
    const nextLine = lineNum + 1 < lines.length ? lines[lineNum + 1] : '';
    const isHeader = !prevLine.trim().startsWith('|') || nextLine.match(/^\|[\s\-:|]+\|$/);

    if (isHeader) {
      formatOps.push({startIdx: rowStart, endIdx: rowStart + rowText.length, type: 'bold'});
    }
    currentIdx += rowText.length;
    continue;
  }

  if (line.trim() === '') {
    plainText += '\n';
    currentIdx += 1;
    continue;
  }

  // Headings
  let style = null;
  let cleanLine = line;
  if (line.startsWith('#### ')) { style = 'HEADING_4'; cleanLine = line.substring(5); }
  else if (line.startsWith('### ')) { style = 'HEADING_3'; cleanLine = line.substring(4); }
  else if (line.startsWith('## ')) { style = 'HEADING_2'; cleanLine = line.substring(3); }
  else if (line.startsWith('# ')) { style = 'HEADING_1'; cleanLine = line.substring(2); }

  let isBullet = false, isNumbered = false;
  if (cleanLine.match(/^[-*]\s/)) { isBullet = true; cleanLine = cleanLine.replace(/^[-*]\s/, ''); }
  if (cleanLine.match(/^\d+\.\s/)) { isNumbered = true; cleanLine = cleanLine.replace(/^\d+\.\s/, ''); }

  // Links
  const linkPositions = [];
  let tempLine = cleanLine.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (match, text, url) => {
    linkPositions.push({text, url});
    return text;
  });

  // Bold
  const boldPositions = [];
  let processed = '';
  let lastIdx2 = 0;
  const boldRx = /\*\*(.+?)\*\*/g;
  let m;
  while ((m = boldRx.exec(tempLine)) !== null) {
    processed += tempLine.substring(lastIdx2, m.index);
    boldPositions.push({start: processed.length, end: processed.length + m[1].length});
    processed += m[1];
    lastIdx2 = m.index + m[0].length;
  }
  processed += tempLine.substring(lastIdx2);

  const lineText = processed + '\n';
  const lineStart = currentIdx;
  plainText += lineText;

  if (style) formatOps.push({startIdx: lineStart, endIdx: lineStart + lineText.length, type: 'heading', style});
  if (isBullet) formatOps.push({startIdx: lineStart, endIdx: lineStart + lineText.length, type: 'bullet'});
  if (isNumbered) formatOps.push({startIdx: lineStart, endIdx: lineStart + lineText.length, type: 'numbered'});

  for (const bp of boldPositions) {
    formatOps.push({startIdx: lineStart + bp.start, endIdx: lineStart + bp.end, type: 'bold'});
  }

  for (const lp of linkPositions) {
    const pos = processed.indexOf(lp.text);
    if (pos >= 0) {
      formatOps.push({startIdx: lineStart + pos, endIdx: lineStart + pos + lp.text.length, type: 'link', url: lp.url});
    }
  }

  currentIdx += lineText.length;
}

// Build requests
requests.push({ insertText: { location: { index: 1 }, text: plainText } });

for (const op of formatOps) {
  if (op.type === 'heading') {
    requests.push({ updateParagraphStyle: { range: { startIndex: op.startIdx, endIndex: op.endIdx }, paragraphStyle: { namedStyleType: op.style }, fields: 'namedStyleType' } });
  }
  if (op.type === 'bullet') {
    requests.push({ createParagraphBullets: { range: { startIndex: op.startIdx, endIndex: op.endIdx }, bulletPreset: 'BULLET_DISC_CIRCLE_SQUARE' } });
  }
  if (op.type === 'numbered') {
    requests.push({ createParagraphBullets: { range: { startIndex: op.startIdx, endIndex: op.endIdx }, bulletPreset: 'NUMBERED_DECIMAL_NESTED' } });
  }
  if (op.type === 'bold') {
    requests.push({ updateTextStyle: { range: { startIndex: op.startIdx, endIndex: op.endIdx }, textStyle: { bold: true }, fields: 'bold' } });
  }
  if (op.type === 'link') {
    requests.push({ updateTextStyle: { range: { startIndex: op.startIdx, endIndex: op.endIdx }, textStyle: { link: { url: op.url } }, fields: 'link' } });
  }
}

return [{ json: { doc_id: docId, doc_url: docUrl, requests: requests } }];

// Zusammenfassung
const meta = $('Parse Meta & Assemble Final').item.json.meta;
const wordCount = $('Parse Meta & Assemble Final').item.json.word_count;
const docUrl = $('Prepare Doc Content').item.json.doc_url;
const keyword = $('Extract Input Data').item.json.keyword;

return [{
  json: {
    success: true,
    keyword: keyword,
    meta_title: meta.meta_title,
    meta_description: meta.meta_description,
    url_slug: meta.url_slug,
    word_count: wordCount,
    google_doc_url: docUrl,
    message: `Content für "${keyword}" erstellt (${wordCount} Wörter). Doc: ${docUrl}`
  }
}];

// WDF*IDF Abdeckungsprüfung für den gesamten Beitrag
const article = $('Extract Final Article').item.json.final_article.toLowerCase();
const wdfTermsRaw = $('Extract Input Data').item.json.wdf_idf_terms_json;
let wdfTerms;
try {
  wdfTerms = typeof wdfTermsRaw === 'string' ? JSON.parse(wdfTermsRaw) : wdfTermsRaw;
} catch(e) { wdfTerms = []; }

if (!wdfTerms || wdfTerms.length === 0) {
  return [{ json: { wdf_idf_check: 'Keine WDF*IDF Terme vorhanden', coverage_pct: 0, missing_terms: [], found_terms: [] } }];
}

const found = [];
const missing = [];
for (const t of wdfTerms) {
  const term = (t.term || t).toLowerCase();
  if (article.includes(term)) {
    found.push({ term, score: t.score || 0 });
  } else {
    missing.push({ term, score: t.score || 0 });
  }
}

const coveragePct = Math.round((found.length / wdfTerms.length) * 100);

// Top 15 fehlende Terme (nach Score sortiert)
const topMissing = missing.sort((a, b) => b.score - a.score).slice(0, 15);

return [{
  json: {
    coverage_pct: coveragePct,
    found_count: found.length,
    total_terms: wdfTerms.length,
    missing_count: missing.length,
    top_missing_terms: topMissing.map(t => `${t.term} (${t.score})`).join(', '),
    found_terms: found.map(t => t.term),
    needs_optimization: coveragePct < 60
  }
}];

// Optimierten Artikel extrahieren und als final_article ersetzen
const response = $input.all()[0].json;
const optimizedArticle = response.content?.[0]?.text || $('Extract Final Article').item.json.final_article;

// Überschreibe final_article für die nachfolgenden Nodes
return [{ json: { final_article: optimizedArticle } }];

// Merge: nimmt optimierten Artikel falls vorhanden, sonst Original
const items = $input.all();
// Der letzte Input ist der richtige (entweder optimiert oder original)
const finalArticle = items[items.length - 1].json.final_article 
  || $('Extract Final Article').item.json.final_article;

return [{ json: { final_article: finalArticle } }];

